  const tabs = $$("[data-step-btn]", wizard);
  const panes = $$("[data-step-pane]", wizard);
  const btnPrev = $("#btnPrev"), btnNext = $("#btnNext"), btnFinish = $("#btnFinish");
  const progress = $("#discProgress");
  const body = $("#wizardBody");

  let step = 0;

  // ---------- render ----------
  const render = () => {
    tabs.forEach(t => {
      const act = +t.dataset.stepBtn === step;
      t.classList.toggle("is-active", act);
      t.setAttribute("aria-selected", act ? "true" : "false");
    });
    panes.forEach(p => p.classList.toggle("is-active", +p.dataset.stepPane === step));
    btnPrev.disabled = step === 0;
    btnNext.hidden = step === 7;
    btnFinish.hidden = step !== 7;
    progress.style.width = ((step+1)/8*100) + "%";
    // center active tab on narrow screens
    if (matchMedia("(max-width: 1024px)").matches) {
      const sc = $(".wizard__tabs");
      const t = tabs[step];
      if (sc && t) {
        const r = t.getBoundingClientRect(), c = sc.getBoundingClientRect();
        const target = sc.scrollLeft + (r.left - c.left) + r.width/2 - sc.clientWidth/2;
        sc.scrollTo({left: Math.max(0, Math.min(target, sc.scrollWidth - sc.clientWidth)), behavior: "smooth"});
      }
    }
  };
  const setStep = n => { step = Math.max(0, Math.min(7, n)); render(); body.scrollTo({top:0, behavior:"smooth"}); };

  tabs.forEach(t => t.addEventListener("click", () => setStep(+t.dataset.stepBtn)));
  btnPrev.addEventListener("click", () => setStep(step-1));
  btnNext.addEventListener("click", () => setStep(step+1));

  // ---------- position numbers in cards ----------
  const refreshPos = (ul) => {
    let i = 1;
    $$(":scope > li", ul).forEach(li => {
      const p = $(".disc-pos", li) || (() => {
        const el = document.createElement("span"); el.className = "disc-pos";
        li.insertBefore(el, li.firstChild); return el;
      })();
      p.textContent = i++;
    });
  };
  $$("ul.disc-list", wizard).forEach(ul => {
    $$(":scope > li", ul).forEach(li => {
      // ensure text span wrapper and handle
      if (!$(".disc-txt", li)) {
        const t = document.createElement("span"); t.className = "disc-txt";
        t.textContent = li.textContent.trim();
        li.replaceChildren();
      }
      if (!$(".disc-handle", li)) {
        const h = document.createElement("span"); h.className = "disc-handle"; h.innerHTML = GHOST.innerHTML.trim();
        li.appendChild(h);
      }
    });
    refreshPos(ul);
  });
  const GHOST = $("#ghostTpl");

  // ---------- sortable (pointer events, works on mouse + touch, no libs) ----------
  const makeSortable = (ul) => {
    let dragLi = null, ghost = null, offX = 0, offY = 0;

    const onPointerDown = (e) => {
      const li = e.target.closest("li.disc-item");
      if (!li || !ul.contains(li)) return;
      // allow click through if it's the ghost itself? no
      if (e.pointerType === "touch" && e.pointerId === undefined) return;
      e.preventDefault();
      dragLi = li;
      const r = li.getBoundingClientRect();
      offX = e.clientX - r.left; offY = e.clientY - r.top;

      const g = GHOST.content.firstElementChild.cloneNode(true);
      g.style.width = r.width + "px";
      g.style.position = "fixed";
      g.style.left = r.left + "px";
      g.style.top = r.top + "px";
      g.style.margin = "0";
      g.classList.add("drag-ghost");
      g.querySelector(".disc-txt").textContent = $(".disc-txt", li).textContent;
      g.querySelector(".disc-pos").textContent = $(".disc-pos", li).textContent;
      document.body.appendChild(g);
      ghost = g;

      li.classList.add("drag-phantom");
      ul.classList.add("is-reordering");

      const move = (ev) => {
        if (!ghost) return;
        ghost.style.left = (ev.clientX - offX) + "px";
        ghost.style.top = (ev.clientY - offY) + "px";
        const lis = $$(":scope > li", ul);
        let best = null, bestD = Infinity;
        for (const x of lis) {
          if (x === li) { x.classList.remove("is-over"); continue; }
          const rr = x.getBoundingClientRect();
          // find insertion point by center
          if (ev.clientY < rr.top + rr.height/2 || ev.clientX < rr.left) {
            const d = Math.abs(ev.clientY - (rr.top + rr.height/2)) + Math.abs(ev.clientX - (rr.left+rr.width/2));
            if (d < bestD) { bestD = d; best = x; }
          }
        }
        lis.forEach(x => x.classList.remove("is-over"));
        if (best && best !== li) {
          ul.insertBefore(li, best);
          refreshAll(ul);
        } else {
          // drop at end
          const last = lis[lis.length-1];
          if (last !== li) { ul.appendChild(li); refreshAll(ul); }
        }
      };
      const up = () => {
        document.removeEventListener("pointermove", move);
        document.removeEventListener("pointerup", up);
        document.removeEventListener("pointercancel", up);
        if (ghost) { ghost.remove(); ghost = null; }
        if (dragLi) { dragLi.classList.remove("drag-phantom"); dragLi.classList.remove("is-dragging"); dragLi = null; }
        ul.classList.remove("is-reordering");
        ul.querySelectorAll("li").forEach(x => x.classList.remove("is-over"));
        const items = $$(":scope > li", ul);
        items.forEach(x => x.classList.remove("is-over"));
        refreshAll(ul);
      };
      document.addEventListener("pointermove", move);
      document.addEventListener("pointerup", up);
      document.addEventListener("pointercancel", up);
    };

    ul.addEventListener("pointerdown", onPointerDown);
  };

  const refreshAll = (ul) => { refreshPos(ul); };
  $$("ul.disc-list", wizard).forEach(makeSortable);

  // ---------- open / close / finish ----------
  const show=(el,c)=>el.classList.add(c);
  const hide=(el,c)=>el.classList.remove(c);
  let lastFocus = null;

  const openWizard = () => {
    lastFocus = document.activeElement;
    show(wizard, "is-open");
    wizard.setAttribute("aria-hidden","false");
    document.documentElement.style.overflow = "hidden";
    $("btnClose").focus({preventScroll:true});
    render();
    window.scrollTo({top: wizard.getBoundingClientRect().top + window.scrollY - 30, behavior:"smooth"});
  };
  const closeWizard = () => {
    hide(wizard, "is-open");
    wizard.setAttribute("aria-hidden","true");
    document.documentElement.style.overflow = "";
    if (lastFocus && lastFocus.focus) lastFocus.focus({preventScroll:true});
  };

  $("#btnOpen").addEventListener("click", openWizard);
  $("#btnClose").addEventListener("click", closeWizard);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && wizard.classList.contains("is-open")) closeWizard();
  });

  // ---------- scoring ----------
  const collect = () => {
    const out = [];
    $$("ul.disc-list", wizard).forEach(ul => {
      $$(":scope > li", ul).forEach((li, idx) => {
        out.push({pos: idx, type: li.dataset.type});
      });
    });
    return out;
  };
  const score = (payload) => {
    const maj = [], min = [];
    payload.forEach(x => { if (x.pos===0) maj.push(x.type); if (x.pos===3) min.push(x.type); });
    const cnt=(a,c)=>a.reduce((n,x)=>n+(x===c?1:0),0);
    return {
      d: cnt(maj,"d")-cnt(min,"d"),
      i: cnt(maj,"i")-cnt(min,"i"),
      s: cnt(maj,"s")-cnt(min,"s"),
      c: cnt(maj,"c")-cnt(min,"c"),
    };
  };

  const DESC = {
    d: ["D — Доминирование", "Прагматичность, решительность, ориентация на результат и задачи. В конфликте — нацелен на решение, а не на уступки."],
    i: ["I — Влияние", "Коммуникабельность, оптимизм, ориентация на людей и энтузиазм. В конфликте — нацелен на убеждение и сплочение."],
    s: ["S — Стабильность", "Добрососедливость, надёжность, ориентация на процесс и поддержку. В конфликте — нацелен на компромисс и удержание."],
    c: ["C — Соблюдение", "Внимательность к деталям, системность, ориентация на правила и процедуры. В конфликте — нацелен на анализ и обоснование."]
  };

  const TOPDESC = { d:"D — Доминирование", i:"I — Влияние", s:"S — Стабильность", c:"C — Соблюдение" };

  const renderResult = (res) => {
    $("#scoreLine").textContent = `D:${res.d}, I:${res.i}, S:${res.s}, C:${res.c}`;
    const max = Math.max(1, ...[res.d,res.i,res.s,res.c].map(v=>Math.abs(v)));
    const pct = v => v < 0 ? 0 : (v / max) * 88 + 6;
    const bar = (id, v) => { $("#val"+id).textContent = v; $("#bar"+id).style.width = pct(v) + "%"; };
    bar("D", res.d); bar("I", res.i); bar("S", res.s); bar("C", res.c);

    // radar
    const pts = [];
    const center = 105, rad = 90;
    const ang = { d: -90, i: 0, s: 90, c: 180 };
    const val = { d:res.d, i:res.i, s:res.s, c:res.c };
    for (const k of ["d","i","s","c"]) {
      const a = (ang[k]*Math.PI)/180;
      const r = Math.abs(val[k]) / max * rad * 0.92;
      pts.push([center + Math.cos(a)*r, center + Math.sin(a)*r]);
    }
    const ring = r => ["d","i","s","c"].map(k=>{const a=(ang[k]*Math.PI)/180;return `${center+Math.cos(a)*r},${center+Math.sin(a)*r}`}).join(" ");
    const lines = ["d","i","s","c"].map(k=>{const a=(ang[k]*Math.PI)/180;return `M${center} ${center} L${center+Math.cos(a)*rad} ${center+Math.sin(a)*rad}`}).join(" ");
    const labels = [["D", center, center-rad-14],["I", center+rad+16, center+6],["S", center, center+rad+20],["C", center-rad-14, center+6]];
    const radarSvg = `<svg viewBox="0 0 210 210">
      <polygon points="${ring(rad)}" fill="none" stroke="rgba(0,0,0,.12)" stroke-width="1"/>
      <polygon points="${ring(rad*0.55)}" fill="none" stroke="rgba(0,0,0,.08)" stroke-width="1"/>
      <path d="${lines}" stroke="rgba(0,0,0,.10)" fill="none"/>
      <polygon points="${pts.map(p=>p.join(",")).join(" ")}" fill="rgba(31,91,214,.22)" stroke="#1F5BD6" stroke-width="2" stroke-linejoin="round"/>
      ${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#1F5BD6" stroke="#fff" stroke-width="1.5"/>`).join("")}
      ${labels.map(([l,x,y])=>`<text x="${x}" y="${y}" font-size="15" font-weight="800" text-anchor="middle" fill="#54637A">${l}</text>`).join("")}
    </svg>`;
    $("#radar").innerHTML = radarSvg;

    // top trait
    const entries = Object.entries(res).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1]));
    const top = entries[0];
    const [k,v] = top;
    const notesEl = $("#resultNotes");
    notesEl.innerHTML = "";
    const add = (b, p) => {
      const div = document.createElement("div");
      div.className = "result__note";
      const bd = document.createElement("b"); bd.textContent = b;
      const pp = document.createElement("p"); pp.textContent = p;
      div.append(bd, pp);
      notesEl.appendChild(div);
    };
    if (v >= 0) {
      add(TOPDESC[k] + ` (сильная сторона)`, DESC[k][1]);
      const others = entries.slice(1,3);
      if (others.length) {
        const [k2,v2] = others[0];
        add(TOPDESC[k2] + ` (вторая по силе)`, DESC[k2][1]);
      }
    } else {
      add(TOPDESC[k].replace(/^[A-Z] — /,"") + " — наименее выраженное", "По этой шкале вы в первую очередь уступаете другим, поэтому эта черта проявляется реже.");
      const topPos = entries.filter(([_,vv])=>vv>0);
      if (topPos.length) {
        const [k2] = topPos[0];
        add(TOPDESC[k2] + ` (сильная сторона)`, DESC[k2][1]);
      }
    }

    show($("#resultCard"), "is-open");
    show($("#resultChart"), "is-open");
    $("#result").firstChild.style.display = "block";
    wizard.style.display = "none";
    $("#btnOpen").style.display = "none";
    $("#fabDone").classList.add("is-open");
    // scroll
    setTimeout(()=> $("#result").scrollIntoView({behavior:"smooth", block:"start"}), 60);
  };

  const reset = (full) => {
    hide($("#resultCard"), "is-open");
    hide($("#resultChart"), "is-open");
    $("#resultNotes").innerHTML = "";
    $("#radar").innerHTML = "";
    ["D","I","S","C"].forEach(id => { $("#bar"+id).style.width = "0"; $("#val"+id).textContent = "0"; });
    wizard.style.display = "";
    $("#btnOpen").style.display = "";
    $("#fabDone").classList.remove("is-open");
    step = 0;

    // restore original order of items in each ul (as loaded)
    const originalOrder = {
      0: [["i","Экспресcивный"],["c","Покладистый"],["d","Волевой"],["s","Осторожный"]],
      1: [["d","Пылкий"],["i","Разговорчивый"],["s","Добродушный"],["c","Сдержанный"]],
      2: [["i","Любитель приключений"],["c","Энтузиаст"],["d","Исполнитель инструкций"],["s","Верный"]],
      3: [["d","Настойчивый"],["c","Осторожный"],["i","Эмоциональный"],["s","Удовлетворенный"]],
      4: [["s","Довольный"],["d","Нетерпеливый"],["i","Убедительный"],["c","Безропотный"]],
      5: [["c","Смиренный"],["s","Умеющий слушать"],["i","Душа компании"],["d","Волевой"]],
      6: [["c","Правильный"],["d","Первоходец"],["s","Спокойный"],["i","Влиятельный"]],
      7: [["c","Почтительный"],["i","Контактный"],["d","Агрессивный"],["s","Мягкий"]],
      8: [["i","Весельчак"],["s","Покорный"],["c","Тактичный"],["d","Соперничающий"]],
      9: [["c","Точный"],["d","Доминирующий"],["s","Охотный"],["i","Притягательный"]],
      10: [["i","Уравновешенный"],["c","Уступчивый"],["d","Идущий на риск"],["s","Услужливый"]],
      11: [["c","Осмотрительный"],["s","Добрососедский"],["d","Энергичный"],["i","Убедительный"]],
      12: [["s","Уравновешенный"],["i","Мотивирующий"],["c","Щепетильный"],["d","Решительный"]],
      13: [["i","Уверенный"],["c","Готовый к сотрудничеству"],["s","Беззаботный"],["d","Аргументирующий"]],
      14: [["s","Сдержанный"],["d","Прямой"],["c","Строгий"],["i","Убедительный"]],
      15: [["c","Застенчивый"],["d","Требовательный"],["s","Терпеливый"],["i","Очаровательный"]],
      16: [["d","Неугомонный"],["c","Дисциплинированный"],["i","Вдохновляющий"],["s","Внимательный"]],
      17: [["s","Обязательный"],["i","Оживленный"],["d","Решительный"],["c","Точный"]],
      18: [["c","Добросовестный"],["i","Компанейский"],["s","Добрый"],["d","Уверенный в себе"]],
      19: [["c","Дипломатичный"],["d","Отважный"],["s","Сочувствующий"],["i","Оптимистичный"]],
      20: [["d","Настойчивый"],["i","Общительный"],["s","Постоянный"],["c","Организованный"]],
      21: [["c","Соглашающийся"],["s","Владеющий собой"],["d","Шутливый"],["i","Настойчивый"]],
      22: [["i","Обаятельный"],["d","Позитивный"],["s","Снисходительный"],["c","Требовательный"]],
      23: [["i","Коммуникабельный"],["d","Смелый"],["c","Перфекционист"],["s","Сдержанный"]]
    };
    const uls = $$("ul.disc-list", wizard);
    uls.forEach((ul, idx) => {
      const items = $$(":scope > li", ul);
      // sort back to original
      const map = new Map(items.map(li => [li.dataset.type + "|" + $(".disc-txt", li).textContent.trim(), li]));
      const order = originalOrder[idx] || [];
      order.forEach(([type, txt]) => {
        const key = type + "|" + txt;
