(() => {
  "use strict";
  const $  = (s, r=document) => r.querySelector(s);
  const $$ = (s, r=document) => Array.from(r.querySelectorAll(s));

  const wizard   = $("#wizard");
  const tabs     = $$("[data-step-btn]", wizard);
  const panes    = $$("[data-step-pane]", wizard);
  const btnPrev  = $("#btnPrev");
  const btnNext  = $("#btnNext");
  const btnFinish= $("#btnFinish");
  const progress = $("#discProgress");
  const bodySc   = $("#wizardBody");
  const bodyMain = $("#pageMain");
  const wizardEl = $("#wizard");
  const resultEl = $("#result");
  const btnOpen  = $("#btnOpen");
  const btnClose = $("#btnClose");
  const fabDone  = $(".result-done");

  let step = 0;
  let finished = false;

  // ---------------- rendering ----------------
  const render = () => {
    tabs.forEach(t => {
      const act = +t.dataset.stepBtn === step;
      t.classList.toggle("is-active", act);
      t.setAttribute("aria-selected", act ? "true" : "false");
    });
    panes.forEach(p => p.classList.toggle("is-active", +p.dataset.stepPane === step));
    btnPrev.disabled = step === 0;
    btnNext.hidden   = step === 7;
    btnFinish.hidden = step !== 7;
    progress.style.width = ((step + 1) / 8 * 100) + "%";
    bodyScrollReset();
    if (matchMedia("(max-width: 1080px)").matches) centerActiveTab();
  };

  const centerActiveTab = () => {
    const sc = $(".wizard__tabs");
    const t = tabs[step];
    if (!sc || !t) return;
    const r = t.getBoundingClientRect();
    const c = sc.getBoundingClientRect();
    const target = sc.scrollLeft + (r.left - c.left) + r.width / 2 - sc.clientWidth / 2;
    sc.scrollTo({ left: Math.max(0, Math.min(target, sc.scrollWidth - sc.clientWidth)), behavior: "smooth" });
  };

  const bodyScrollReset = () => bodySc.scrollTo({ top: 0, behavior: "auto" });

  const setStep = (n) => { step = Math.max(0, Math.min(7, n)); render(); };

  tabs.forEach(t => t.addEventListener("click", () => setStep(+t.dataset.stepBtn)));
  btnPrev.addEventListener("click", () => setStep(step - 1));
  btnNext.addEventListener("click", () => setStep(step + 1));

  // ---------------- decorate items ----------------
  const GHOST = `
    <span class="disc-pos">1</span>
    <span class="disc-txt"></span>
    <span class="disc-grip" aria-hidden="true">
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><circle cx="6" cy="4" r="1.3" fill="#B3B3B3"/><circle cx="6" cy="8" r="1.3" fill="#B3B3B3"/><circle cx="6" cy="12" r="1.3" fill="#B3B3B3"/><circle cx="10" cy="4" r="1.3" fill="#B3B3B3"/><circle cx="10" cy="8" r="1.3" fill="#B3B3B3"/><circle cx="10" cy="12" r="1.3" fill="#B3B3B3"/></svg>
    </span>`;

  const decorate = (li) => {
    if (li.querySelector(".disc-pos")) return;
    const txt = li.dataset.text || li.textContent.trim();
    li.textContent = "";
    const holder = document.createElement("span");
    holder.innerHTML = GHOST;
    Array.from(holder.childNodes).forEach(n => li.appendChild(n.cloneNode(true)));
    li.querySelector(".disc-txt").textContent = txt;
  };

  const refreshPos = (ul) => {
    let i = 1;
    $$(":scope > li", ul).forEach(li => {
      const p = $(".disc-pos", li);
      if (p) p.textContent = i++;
    });
  };

  const moveLi = (li, dir) => {
    const ul = li.parentElement;
    const list = $$(":scope > li", ul);
    const idx = list.indexOf(li);
    const target = idx + dir;
    if (target < 0 || target >= list.length) return;
    ul.insertBefore(li, list[target]);
    refreshPos(ul);
    li.blur();
  };

  $$("ul.disc-list", wizard).forEach(ul => {
    $$(":scope > li", ul).forEach(li => {
      decorate(li);
      const btnUp = document.createElement("button");
      btnUp.type = "button"; btnUp.className = "disc-move"; btnUp.disabled = true;
      btnUp.setAttribute("aria-label", "Переместить выше");
      btnUp.innerHTML = '<svg width="12" height="12" viewBox="0 0 12 12" preserveAspectRatio="none"><path d="M6 1 1 8h10L6 1Z" fill="#54637A"/></svg>';
      btnUp.addEventListener("click", (e) => { e.stopPropagation(); moveLi(li, -1); if (e.detail) btnUp.focus({preventScroll:true}); });
      const btnDn = document.createElement("button");
      btnDn.type = "button"; btnDn.className = "disc-move"; btnDn.disabled = false;
      btnDn.setAttribute("aria-label", "Переместить ниже");
      btnDn.innerHTML = '<svg width="12" height="12" viewBox="0 0 12 12" preserveAspectRatio="none"><path d="M6 11 1 4h10L6 11Z" fill="#54637A"/></svg>';
      btnDn.addEventListener("click", (e) => { e.stopPropagation(); moveLi(li, +1); if (e.detail) btnDn.focus({preventScroll:true}); });
      const grp = document.createElement("span");
      grp.className = "disc-move"; grp.style.flexDirection = "row"; grp.style.gap = "2px"; grp.style.opacity = 1;
      grp.append(btnUp, btnDn);
      li.appendChild(grp);

      li.addEventListener("keydown", (e) => {
        if (e.key === "ArrowUp")   { e.preventDefault(); moveLi(li, -1); li.focus({preventScroll:true}); }
        if (e.key === "ArrowDown") { e.preventDefault(); moveLi(li, +1); li.focus({preventScroll:true}); }
      });
    });

    ul.addEventListener("keydown", (e) => {
      const li = liAt(ul);
      if (li) {
        const items = $$(":scope > li", ul);
        const idx = items.indexOf(li);
        if (e.key === "ArrowUp")   { e.preventDefault(); btnMove(li, -1); }
        if (e.key === "ArrowDown") { e.preventDefault(); btnMove(li, +1); }
      }
    });
  });

  const liAt = (ul) => null; // no-op placeholder
  const btnMove = (li, dir) => moveLi(li, dir);

  $$("#wizard ul.disc-list li.disc-item").forEach(li => li.tabIndex = 0);
  $$("ul.disc-list", wizard).forEach(refreshPos);

  // ---------------- drag-and-drop (pointer events) ----------------
  const makeSortable = (ul) => {
    let dragLi = null, ghost = null, offX = 0, offY = 0, started = false;

    const down = (e) => {
      const li = e.target.closest("li.disc-item");
      if (!li || !ul.contains(li)) return;
      if (e.button !== undefined && e.button !== 0) return;

      const r = li.getBoundingClientRect();
      offX = e.clientX - r.left; offY = e.clientY - r.top;
      started = false;

      const g = li.cloneNode(true);
      g.classList.add("drag-ghost");
      g.removeAttribute("tabindex");
      g.style.width = r.width + "px";
      g.style.left  = r.left + "px";
      g.style.top   = r.top + "px";
      g.querySelector(".disc-move").style.display = "none";
      const gp = g.querySelector(".disc-pos"); if (gp) gp.style.background = "var(--blue)", gp.style.color="#fff";
      document.body.appendChild(g);
      ghost = g;
      li.classList.add("is-ghost");
      dragLi = li;

      const onMove = (ev) => {
        if (!started) {
          const dx = ev.movementX, dy = ev.movementY;
          // start drag after small threshold so clicks work
          if (Math.hypot(ev.clientX - (r.left + offX), ev.clientY - (r.top + offY)) < 4) return;
          started = true;
