        }
        ghost.style.left = (ev.clientX - offX) + "px";
        ghost.style.top  = (ev.clientY - offY) + "px";
        // find insertion
        const lis = $$(":scope > li", ul);
        let before = null;
        for (const x of lis) {
          if (x === li) continue;
          const rr = x.getBoundingClientRect();
          if (ev.clientY < rr.top + rr.height / 2) { before = x; break; }
        }
        lis.forEach(x => x.classList.remove("is-target"));
        if (before) before.classList.add("is-target");
        if (before === li && (ul.previousElementSibling !== li || true)) {
          // no-op
        }
        if (before) {
          ul.insertBefore(li, before);
        } else {
          ul.appendChild(li);
        }
        lis.forEach(x => x.classList.remove("is-target"));
        refreshPos(ul);
      };

      const onUp = () => {
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", onUp);
        document.removeEventListener("pointercancel", onUp);
        ghost && ghost.remove();
        ghost = null;
        li.classList.remove("is-ghost", "is-dragging");
        dragLi = null;
        ul.querySelectorAll("li").forEach(x => x.classList.remove("is-target"));
        refreshPos(ul);
      };

      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
      document.addEventListener("pointercancel", onUp);
    };

    ul.addEventListener("pointerdown", down);
  };
  $$("ul.disc-list", wizard).forEach(makeSortable);

  // ---------------- open / close wizard ----------------
  let lastFocus = null;
  const lockScroll = (lock) => {
    document.documentElement.style.overflow = lock ? "hidden" : "";
    document.body.style.overflow = lock ? "hidden" : "";
  };

  const openWizard = () => {
    if (finished) { showResult(); return; }
    lastFocus = document.activeElement;
    wizardEl.classList.add("is-open");
    wizardEl.removeAttribute("hidden");
    wizardEl.setAttribute("aria-hidden", "false");
    lockScroll(true);
    btnClose.focus({ preventScroll: true });
    render();
    requestAnimationFrame(() => {
      const y = wizardEl.getBoundingClientRect().top + window.scrollY - 28;
      window.scrollTo({ top: y, behavior: "smooth" });
