  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && wizardEl.classList.contains("is-open")) closeWizard();
  });

  // ---------------- scoring ----------------
  const collect = () => {
    const out = [];
    $$("ul.disc-list", wizard).forEach(ul => {
      $$(":scope > li", ul).forEach((li, idx) => out.push({ pos: idx, type: li.dataset.type }));
    });
    return out;
  };
  const score = (payload) => {
    const maj = [], min = [];
    payload.forEach(x => { if (x.pos === 0) maj.push(x.type); if (x.pos === 3) min.push(x.type); });
    const cnt = (a, c) => a.reduce((n, x) => n + (x === c ? 1 : 0), 0);
    return {
      d: cnt(maj,"d")-cnt(min,"d"),
      i: cnt(maj,"i")-cnt(min,"i"),
      s: cnt(maj,"s")-cnt(min,"s"),
      c: cnt(maj,"c")-cnt(min,"c"),
    };
  };

  const LABELS = { D:"Доминирование", I:"Влияние", S:"Стабильность", C:"Соблюдение" };
  const DESC  = {
    D: "Прагматичность, решительность, ориентация на результат и задачи. Не боится конфликтов, если они ведут к решению.",
    I: "Коммуникабельность, оптимизм, ориентация на людей. Убеждает, увлекать, сплотить — в этом сила.",
    S: "Надёжность, поддержание стабильности, ориентация на процесс и людей. Предпочитает компромисс и удержание команды.",
    C: "Системность, внимание к деталям, ориентация на правила и процедуры. Принимает решения на анализе."
  };

  const renderResult = (res) => {
    $("#scoreLine").textContent = `D:${res.d}, I:${res.i}, S:${res.s}, C:${res.c}`;
    const max = Math.max(1, ...[res.d, res.i, res.s, res.c].map(v => Math.abs(v)));
    const pct = v => v <= 0 ? 2 : Math.round((v / max) * 88 + 6);
    const setBar = (k, v) => {
      $("#val" + k).textContent = v;
      $("#bar" + k).style.width = pct(v) + "%";
    };
    setBar("D", res.d); setBar("I", res.i); setBar("S", res.s); setBar("C", res.c);

    // radar: D top, I right, S bottom, C left
    const cx = 105, cy = 119, R = 96;
    const ANGS = { D: -90, I: 0, S: 90, C: 180 };
    const V = { D: res.d, I: res.i, S: res.s, C: res.c };
    const pt = (k, r) => {
      const a = (ANGS[k] * Math.PI) / 180;
      return [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
    };
    const poly = (r) => Object.keys(ANGS).map(k => pt(k, r).join(",")).join(" ");
    const vals = Object.keys(ANGS).map(k => pt(k, Math.abs(V[k]) / max * R * 0.92).join(",")).join(" ");
    const spokes = Object.keys(ANGS).map(k => `M${cx} ${cy} L${pt(k, R).join(" ")}`).join(" ");
    const labels = [["D", cx, cy - R - 14],["I", cx + R + 18, cy + 5],["S", cx, cy + R + 20],["C", cx - R - 16, cy + 5]];
    $("#radar").innerHTML =
      `<svg viewBox="0 0 210 238" role="img" aria-label="${["D","I","S","C"].map(k => `${k}:${V[k]}`).join(", ")}">
        <polygon points="${poly(R)}" fill="none" stroke="rgba(0,0,0,.14)" stroke-width="1"/>
        <polygon points="${poly(R*.55)}" fill="none" stroke="rgba(0,0,0,.09)" stroke-width="1"/>
        <polygon points="${poly(R*.28)}" fill="none" stroke="rgba(0,0,0,.05)" stroke-width="1"/>
        <path d="${spokes}" stroke="rgba(0,0,0,.10)" fill="none"/>
        <polygon points="${vals}" fill="rgba(31,91,214,.20)" stroke="#1F5BD6" stroke-width="2" stroke-linejoin="round"/>
        ${["D","I","S","C"].map(k => { const [x,y]=pt(k, Math.abs(V[k])/max * R * 0.92); return `<circle cx="${x}" cy="${y}" r="4.5" fill="#1F5BD6" stroke="#fff" stroke-width="1.6"/>`; }).join("")}
        ${labels.map(([l,x,y]) => `<text x="${x}" y="${y}" font-size="15" font-weight="800" text-anchor="middle" fill="#54637A">${l}</text>`).join("")}
      </svg>`;

    // notes: top positive trait + lowest trait
    const entries = Object.entries(res).sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]));
    const topPositive = entries.filter(e => e[1] > 0).sort((a,b) => b[1]-a[1]);
    const topNegative = entries.filter(e => e[1] < 0).sort((a,b) => Math.abs(b[1]) - Math.abs(a[1]));
    const notes = $("#resultNotes");
    notes.innerHTML = "";
    const addNote = (cls, lab, txt) => {
      const d = document.createElement("div");
      d.className = "res-note " + cls;
      d.innerHTML = `<span class="res-note__lab">${lab}</span><p>${txt}</p>`;
      notes.appendChild(d);
    };
    if (topPositive.length) {
      const [k, v] = topPositive[0];
      addNote("res-note--top", "Сильная сторона", `<b>${LABELS[k]}</b> — ${DESC[k]}`);
      if (topPositive.length > 1) {
        const [k2, v2] = topPositive[1];
        addNote("", "Второй по силе", `<b>${LABELS[k2]}</b> — ${DESC[k2]}`);
      }
    }
    if (topNegative.length) {
      const [k, v] = topNegative[0];
      addNote("res-note--low", "Наименее выраженное", `<b>${LABELS[k]}</b> — эта черта в вашем стиле проявляется реже всего по результатам теста.`);
    }

    // show
    resultEl.querySelectorAll(".res-col").forEach(c => c.classList.add("is-open"));
    wizardEl.style.display = "none";
    btnOpen.style.display = "none";
    fabDone.classList.add("is-open");
    fabDone.scrollIntoView({ behavior: "smooth", block: "nearest" });
    setTimeout(() => resultEl.scrollIntoView({ behavior: "smooth", block: "start" }), 80);
  };

  const hideResult = () => {
    resultEl.querySelectorAll(".res-col").forEach(c => c.classList.remove("is-open"));
    $("#resultNotes").innerHTML = "";
    ["D","I","S","C"].forEach(k => {
      $("#bar" + k).style.width = "0%";
      $("#val" + k).textContent = "0";
    });
  };

  // ---------------- finish / restart ----------------
  btnFinish.addEventListener("click", () => {
    const res = score(collect());
    finished = true;
    renderResult(res);
  });

  const reset = () => {
    finished = false;
    hideResult();
    wizardEl.style.display = "";
    btnOpen.style.display = "";
    fabDone.classList.remove("is-open");

    // restore original item order in each list
    const uls = $$("ul.disc-list", wizard);
    uls.forEach((ul, idx) => {
      const order = O[idx];
      const map = new Map($$(":scope > li", ul).map(li => [li.dataset.text, li]));
      order.forEach(([t, txt]) => {
        const li = map.get(txt);
        if (li) ul.appendChild(li);
      });
      refreshPos(ul);
    });

    step = 0;
    render();
    bodyMain.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  $("#btnRestart").addEventListener("click", reset);
  $("#btnCloseOnResult") && $("#btnCloseOnResult").addEventListener("click", () => {
    reset();
  });

  render();
})();
'''

