:root{
  --blue:#1F5BD6; --blue-soft:#EAF2FA; --green:#3A944A; --green-bar:#6FE28A;
  --ink:#1C1C1C; --ink2:#2C2C2C; --dim:#54637A; --line:rgba(0,0,0,.18); --line-soft:rgba(0,0,0,.12);
}
* { box-sizing: border-box; }
html, body { margin:0; padding:0; }
body{
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  color:var(--ink); background:linear-gradient(165deg,#F4F8FC 0%,#E7F0FA 100%);
  min-height:100vh; -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;
}
a { color:inherit; }

.page{ max-width:1240px; margin:0 auto; padding:44px 24px 70px; }
.page__badge{
  display:inline-flex;align-items:center;gap:10px;background:var(--blue);color:#fff;
  font-size:12.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
  padding:9px 18px;border-radius:999px;margin-bottom:20px;
}
.page h1{ font-size:clamp(34px,5vw,52px); line-height:1.08; margin:0 0 14px; font-weight:800; letter-spacing:-.015em; }
.page__sub{ font-size:18px; line-height:1.55; color:var(--ink2); max-width:820px; margin:0 0 12px; }
.page__lead{ font-size:16.5px; line-height:1.55; color:var(--dim); max-width:820px; margin:0 0 28px; }
.page__actions{ display:flex; align-items:center; gap:18px; flex-wrap:wrap; }

.btn-primary{
  border:0;cursor:pointer;background:var(--blue);color:#fff;font-size:19px;font-weight:700;
  padding:17px 44px;border-radius:999px;display:inline-flex;align-items:center;gap:12px;
  box-shadow:0 14px 30px rgba(31,91,214,.28);
  transition:transform .15s ease, box-shadow .15s ease;
}
.btn-primary:hover{ transform:translateY(-2px); box-shadow:0 18px 38px rgba(31,91,214,.34); }
.btn-primary:active{ transform:translateY(0); }
.btn-primary svg{ display:block; }

.page__hint{ font-size:14.5px; color:var(--dim); display:inline-flex; align-items:center; gap:8px; }
.page__hint svg{ display:block; }

.result-done{
  display:none;align-items:center;gap:8px;font-size:15px;font-weight:700;color:#2B7A3C;
  background:#EAF7EE;border:1px solid #BFE6C8;border-radius:999px;padding:12px 20px;
}
.result-done.is-open{ display:inline-flex; animation:pop .25s ease; }
.result-done svg{ display:block; }
.result-done a{ color:var(--blue); text-decoration:underline; text-underline-offset:3px; }

.section-gap{ height:10px; }

/* ============ wizard ============ */
.wizard{
  margin-top:26px; background:#fff; border-radius:22px; overflow:hidden;
  box-shadow:0 30px 90px rgba(20,40,80,.16); display:none;
}
.wizard.is-open{ display:block; animation:pop .3s ease; }
.wizard__head{ position:relative; padding:44px 56px 12px; text-align:center; }
.wizard__close{
  position:absolute; top:20px; right:22px; width:46px; height:46px;
  border:0; background:transparent; cursor:pointer; opacity:.55;
  display:inline-flex; align-items:center; justify-content:center; border-radius:12px;
}
.wizard__close:hover{ opacity:1; background:rgba(0,0,0,.05); }
.wizard__close svg{ display:block; }
.wizard__title{ font-size:clamp(28px,3.4vw,38px); margin:0 0 10px; font-weight:800; letter-spacing:-.01em; }
.wizard__sub{ font-size:16px; color:var(--dim); margin:0 0 4px; }
.wizard__lead{ font-size:16px; color:var(--dim); margin:0; }
.wizard__tabs{
  padding:2px 40px 10px; display:flex; gap:8px; justify-content:center;
