}
.wizard__tabs::-webkit-scrollbar{ display:none; }
.disc-tab{
  border:0; background:var(--blue-soft); color:var(--ink2); border-radius:10px;
  padding:13px 17px; font-size:16.5px; line-height:1; cursor:pointer; white-space:nowrap; flex:0 0 auto;
  transition:background .15s ease, color .15s ease;
}
.disc-tab:hover{ background:#DCE9F7; }
.disc-tab.is-active{ background:var(--blue); color:#fff; }
.disc-tab:focus-visible{ outline:2px solid var(--blue); outline-offset:2px; }
.wizard__body{ padding:12px 48px 44px; background:#fff; }
.disc-pane{ display:none; }
.disc-pane.is-active{ display:block; animation:fade .18s ease; }
.disc-grid3{ display:grid; grid-template-columns:repeat(3,1fr); gap:22px; margin-top:10px; }

.disc-card{ border:1px solid var(--line); border-radius:12px; overflow:hidden; background:#fff; }
.disc-card__title{ padding:14px 18px 6px; font-size:18px; font-weight:800; letter-spacing:-.01em; }
.disc-card__foot{ padding:6px 18px 14px; font-size:18px; font-weight:800; }

.disc-list{ list-style:none; margin:0; padding:8px; border-radius:10px; border:1px solid var(--line-soft); background:#FBFCFE; }
.disc-item{
  display:flex; align-items:center; gap:10px;
  padding:9px 10px; font-size:16px; color:var(--ink2);
  cursor:grab; user-select:none; background:#fff;
