.disc-item:hover{ box-shadow:0 4px 14px rgba(20,40,80,.10); }
.disc-item:focus, .disc-item:focus-visible{ border-color:rgba(31,91,214,.45); background:#F3F7FF; }
.disc-item .disc-pos{
  flex:0 0 auto; min-width:24px; height:24px; border-radius:8px;
  background:var(--blue-soft); color:var(--blue);
  font-size:12.5px; font-weight:800; display:flex; align-items:center; justify-content:center; padding:0 4px;
}
.disc-item .disc-txt{ flex:1 1 auto; min-width:0; }
.disc-item .disc-move{
  flex:0 0 auto; display:flex; flex-direction:column; gap:1px;
  background:none; border:0; padding:2px; cursor:pointer;
}
.disc-item .disc-move svg{ display:block; opacity:.35; }
.disc-item .disc-move:hover svg, .disc-item .disc-move:focus-visible svg{ opacity:1; }
.disc-item .disc-grip{
  flex:0 0 auto; display:flex; align-items:center; justify-content:center;
  opacity:.4; cursor:grab; border:0; background:none; padding:3px 4px; border-radius:6px;
}
.disc-item .disc-grip:hover{ opacity:.85; background:rgba(0,0,0,.05); }
.disc-item .disc-grip svg{ display:block; }

.disc-item.is-ghost{ opacity:.38; }
.disc-item.is-target{ border-color:rgba(31,91,214,.55); background:#F3F7FF; }
.disc-item.is-dragging{ cursor:grabbing; }

.drag-ghost{
  position:fixed; z-index:2000; pointer-events:none; margin:0;
  box-shadow:0 20px 48px rgba(20,40,80,.32);
}
.drag-ghost .disc-pos{ background:var(--blue); color:#fff; }

.wizard__bar{ margin:22px 6px 0; height:14px; border-radius:999px; background:rgba(0,0,0,.08); overflow:hidden; }
.wizard__bar i{ display:block; height:100%; width:12.5%; border-radius:999px; background:var(--green-bar); transition:width .25s ease; }
.wizard__bar .wizard__pct{
  position:absolute; right:4px; top:-26px; font-size:13px; font-weight:700; color:var(--dim);
}
.wizard__actions{ margin:22px 0 0; display:flex; justify-content:space-between; align-items:center; gap:14px; }
.disc-btn{
  border:1px solid rgba(0,0,0,.22); border-radius:999px; padding:13px 36px;
  font-size:17px; font-weight:600; cursor:pointer; background:#fff; color:var(--ink);
  transition:background .15s ease;
}
.disc-btn:not(:disabled):not([hidden]):hover{ background:#F5F7FA; }
.disc-btn--primary{ border-color:transparent; background:var(--green); color:#fff; }
.disc-btn--primary:not(:disabled):not([hidden]):hover{ background:#338241; }
.disc-btn:disabled{ opacity:.45; cursor:default; }
.disc-btn[hidden]{ display:none; }

/* ============ result ============ */
.result{ margin-top:38px; display:grid; grid-template-columns:1.05fr .95fr; gap:26px; align-items:stretch; }
.result .res-col{ display:none; }
.result .res-col.is-open{ display:block; animation:pop .3s ease; }
.res-card,.res-chart{
  background:#fff; border-radius:20px; padding:38px 42px; box-shadow:0 24px 70px rgba(20,40,80,.14);
}
.res-uptitle{
  display:inline-flex; align-items:center; gap:8px;
  font-size:12.5px; font-weight:800; letter-spacing:.13em;
  text-transform:uppercase; color:var(--blue); margin:0 0 12px;
}
.res-uptitle svg{ display:block; }
.res-card h2{ font-size:28px; margin:0 0 6px; font-weight:800; letter-spacing:-.01em; }
.res-lede{ font-size:15px; line-height:1.55; color:var(--dim); margin:0 0 18px; }
.res-score{ font-size:clamp(23px,2.8vw,31px); font-weight:800; color:var(--blue); margin:4px 0 22px; letter-spacing:.02em; }

.res-notes{ display:grid; gap:12px; }
.res-note{
  display:flex; gap:14px; align-items:flex-start;
  background:#F6F9FD; border:1px solid var(--line-soft); border-radius:14px; padding:15px 17px;
}
.res-note .res-note__lab{
  flex:0 0 auto; min-width:112px; font-size:11.5px; font-weight:800;
  color:var(--blue); text-transform:uppercase; letter-spacing:.08em; line-height:1.5;
  padding-top:2px;
}
.res-note p{ margin:0; font-size:14.5px; line-height:1.55; color:var(--ink2); }
.res-note--top .res-note__lab{ color:#B87D13; }
.res-note--low .res-note__lab{ color:#8A97A8; }

.res-foot{ margin-top:20px; font-size:13px; line-height:1.55; color:#67788F; }
.res-actions{ margin-top:22px; display:flex; gap:12px; flex-wrap:wrap; }
.btn-green{
  border:0; border-radius:999px; padding:13px 28px; font-size:15.5px; font-weight:700;
  cursor:pointer; background:var(--green); color:#fff; display:inline-flex; gap:9px; align-items:center;
  transition:background .15s ease;
}
.btn-green:hover{ background:#338241; }
.btn-green svg{ display:block; }
.btn-ghost{
  border:1px solid rgba(0,0,0,.22); border-radius:999px; padding:13px 28px;
  font-size:15.5px; font-weight:600; cursor:pointer; background:#fff; color:var(--ink);
}
.btn-ghost:hover{ background:#F5F7FA; }

.res-chart--h3{ font-size:19px; margin:0 0 4px; font-weight:800; letter-spacing:-.01em; }
.chart__grid{ display:grid; grid-template-columns:1fr 210px; gap:26px; align-items:center; margin-top:14px; }
.bar-row{ display:grid; grid-template-columns:30px 1fr 44px; gap:12px; align-items:center; margin:12px 0; }
.bar-row .lab{ font-size:17px; font-weight:800; }
.bar-track{ height:15px; border-radius:999px; background:rgba(0,0,0,.07); overflow:hidden; }
.bar-fill{ height:100%; width:0; border-radius:999px; transition:width .8s cubic-bezier(.2,.8,.2,1); }
.bar-row .val{ font-size:14.5px; font-weight:700; text-align:right; color:var(--dim); }
.radar-wrap svg{ width:100%; height:auto; display:block; }

@keyframes pop{ from{ opacity:0; transform:translateY(12px);} to{ opacity:1; transform:none;} }
@keyframes fade{ from{ opacity:.35;} to{ opacity:1;} }

@media (max-width:1080px){
  .result{ grid-template-columns:1fr; }
  .chart__grid{ grid-template-columns:1fr 190px; }
}
@media (max-width:767px){
  .page{ padding:28px 16px 54px; }
  .page h1{ font-size:31px; }
  .page__sub,.page__lead{ font-size:16px; }
  .page__actions{ gap:12px; }
  .wizard{ margin-top:20px; }
  .wizard__head{ padding:30px 20px 6px; }
  .wizard__close{ top:14px; right:14px; width:42px; height:42px; }
  .wizard__tabs{ padding:2px 14px 8px; justify-content:flex-start; }
  .disc-tab{ padding:11px 14px; font-size:15.5px; }
  .wizard__body{ padding:10px 14px 30px; }
  .disc-grid3{ grid-template-columns:1fr; gap:14px; }
  .disc-item{ font-size:15.5px; }
  .wizard__bar{ margin:18px 4px 0; }
  .wizard__actions{ flex-wrap:wrap; justify-content:center; }
  .disc-btn{ padding:12px 30px; font-size:16px; }
  .res-card,.res-chart{ padding:26px 20px; }
  .chart__grid{ grid-template-columns:1fr; }
}

(() => {
  "use strict";
  const $  = (s, r=document) => r.querySelector(s);
  const $$ = (s, r=document) => Array.from(r.querySelectorAll(s));

  const pageMain = $("#pageMain");
  const wizardEl = $("#wizard");
  const resultEl = $("#result");
  const btnOpen  = $("#btnOpen");
  const btnClose = $("#btnClose");
  const btnPrev  = $("#btnPrev");
  const btnNext  = $("#btnNext");
  const btnFinish= $("#btnFinish");
  const tabs     = $$("[data-step-btn]", wizardEl);
  const panes    = $$("[data-step-pane]", wizardEl);
  const progress = $("#discProgress");
  const stepPct  = $("#stepPct");
  const fabDone  = $("#fabDone");

  let step = 0;
  let finished = false;

  // ---------- render ----------
  const render = () => {
    tabs.forEach(t => {
      const act = +t.dataset.stepBtn === step;
      t.classList.toggle("is-active", act);
      t.setAttribute("aria-selected", act ? "true" : "false");
    });
    panes.forEach(p => p.classList.toggle("is-active", +p.dataset.stepPane === step));
    btnPrev.disabled = step === 0;
    btnNext.hidden   = step === 7;
    btnFinish.hidden = step !== 7;
    progress.style.width = ((step + 1) / 8 * 100) + "%";
    stepPct.textContent = (step + 1) + "/8";
    const body = $("#wizardBody");
    body.scrollTo({ top: 0, behavior: "auto" });
    if (matchMedia("(max-width: 1080px)").matches) centerActiveTab();
  };

  const centerActiveTab = () => {
    const sc = $(".wizard__tabs");
    const t = tabs[step];
    if (!sc || !t) return;
    const r = t.getBoundingClientRect();
    const c = sc.getBoundingClientRect();
    const target = sc.scrollLeft + (r.left - c.left) + r.width / 2 - sc.clientWidth / 2;
    sc.scrollTo({ left: Math.max(0, Math.min(target, sc.scrollWidth - sc.clientWidth)), behavior: "smooth" });
  };

  const setStep = n => { step = Math.max(0, Math.min(7, n)); render(); };

  tabs.forEach(t => t.addEventListener("click", () => setStep(+t.dataset.stepBtn)));
  btnPrev.addEventListener("click", () => setStep(step - 1));
  btnNext.addEventListener("click", () => setStep(step + 1));

  // ---------- decorate items + buttons ----------
  const GRIP_HTML =
    '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">' +
    '<circle cx="6" cy="4" r="1.3" fill="#B3B3B3"/><circle cx="6" cy="8" r="1.3" fill="#B3B3B3"/><circle cx="6" cy="12" r="1.3" fill="#B3B3B3"/>' +
    '<circle cx="10" cy="4" r="1.3" fill="#B3B3B3"/><circle cx="10" cy="8" r="1.3" fill="#B3B3B3"/><circle cx="10" cy="12" r="1.3" fill="#B3B3B3"/>' +
    '</svg>';
  const UP_HTML   = '<svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M6 1.5 1.5 8h9L6 1.5Z" fill="#54637A"/></svg>';
  const DN_HTML   = '<svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M6 10.5 1.5 4h9L6 10.5Z" fill="#54637A"/></svg>';

  const refreshPos = (ul) => {
    let i = 1;
    $$(":scope > li", ul).forEach(li => {
      const p = li.querySelector(":scope > .disc-pos");
      if (p) p.textContent = i++;
    });
  };

  const decorate = (li) => {
    if (li.querySelector(":scope > .disc-pos")) return;
    const text = li.dataset.text || li.textContent.trim();
    li.textContent = "";
    const pos = document.createElement("span");
    pos.className = "disc-pos"; pos.textContent = "1";
    const txt = document.createElement("span");
    txt.className = "disc-txt"; txt.textContent = text;
    const grip = document.createElement("span");
    grip.className = "disc-grip"; grip.innerHTML = GRIP_HTML;
    const move = document.createElement("span");
    move.className = "disc-move"; move.style.gap = "1px";
    const up = document.createElement("button");
    up.type = "button"; up.className = "disc-move__btn"; up.innerHTML = UP_HTML;
    up.setAttribute("aria-label", "Переместить выше");
    up.tabIndex = -1;
    const dn = document.createElement("button");
    dn.type = "button"; dn.className = "disc-move__btn"; dn.innerHTML = DN_HTML;
    dn.setAttribute("aria-label", "Переместить ниже");
    dn.tabIndex = -1;
    move.append(up, dn);
    li.append(pos, txt, grip, move);

    up.addEventListener("click", (e) => { e.preventDefault(); moveLi(li, -1); li.focus({ preventScroll:true }); });
    dn.addEventListener("click", (e) => { e.preventDefault(); moveLi(li, +1); li.focus({ preventScroll:true }); });
  };

  const moveLi = (li, dir) => {
    const ul = li.parentElement;
    const list = $$(":scope > li", ul);
    const idx = list.indexOf(li);
    const t = idx + dir;
    if (t < 0 || t >= list.length) return;
    ul.insertBefore(li, list[t]);
    refreshPos(ul);
  };

  $$("ul.disc-list", wizardEl).forEach(ul => {
    $$(":scope > li", ul).forEach(li => {
      decorate(li);
      li.tabIndex = 0;
      li.setAttribute("role", "listitem");
      li.addEventListener("keydown", (e) => {
        if (e.key === "ArrowUp")   { e.preventDefault(); moveLi(li, -1); li.focus({ preventScroll:true }); }
        if (e.key === "ArrowDown") { e.preventDefault(); moveLi(li, +1); li.focus({ preventScroll:true }); }
      });
    });
    ul.setAttribute("role", "list");
    refreshPos(ul);
  });

  // ---------- drag & drop (pointer events: mouse + touch) ----------
  const makeSortable = (ul) => {
    let dragLi = null, ghost = null, offX = 0, offY = 0, started = false, startXY = null;

    const down = (e) => {
      const li = e.target.closest("li.disc-item");
      if (!li || !ul.contains(li)) return;
      if (e.button !== undefined && e.button !== 0) return;
      if (e.target.closest("button")) return;

      e.preventDefault();
      const r = li.getBoundingClientRect();
      offX = e.clientX - r.left;
      offY = e.clientY - r.top;
      startXY = { x: e.clientX, y: e.clientY };
      started = false;

      const g = li.cloneNode(true);
      g.classList.add("drag-ghost");
      g.removeAttribute("tabindex");
      g.style.width = r.width + "px";
      g.style.left = r.left + "px";
      g.style.top = r.top + "px";
      g.style.margin = "0";
      const gp = g.querySelector(":scope > .disc-pos");
      if (gp) { gp.style.background = "var(--blue)"; gp.style.color = "#fff"; }
      const gm = g.querySelector(":scope > .disc-move"); if (gm) gm.style.display = "none";
      const gg = g.querySelector(":scope > .disc-grip"); if (gg) gg.style.display = "none";
      document.body.appendChild(g);
      ghost = g;
      li.classList.add("is-ghost");
      dragLi = li;

      const onMove = (ev) => {
        if (!started) {
          if (Math.hypot(ev.clientX - startXY.x, ev.clientY - startXY.y) < 6) return;
          started = true;
          li.classList.add("is-dragging");
        }
        ghost.style.left = (ev.clientX - offX) + "px";
        ghost.style.top  = (ev.clientY - offY) + "px";

        const lis = $$(":scope > li", ul);
        let before = null;
        for (const x of lis) {
          if (x === li) continue;
          const rr = x.getBoundingClientRect();
          if (ev.clientY < rr.top + rr.height / 2) { before = x; break; }
        }
        lis.forEach(x => x.classList.remove("is-target"));
        if (before) before.classList.add("is-target");

        if (before) ul.insertBefore(li, before);
        else ul.appendChild(li);

        lis.forEach(x => x.classList.remove("is-target"));
        refreshPos(ul);
      };

      const cleanup = () => {
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", cleanup);
        document.removeEventListener("pointercancel", cleanup);
        if (ghost) { ghost.remove(); ghost = null; }
        if (li) {
          li.classList.remove("is-ghost", "is-dragging");
          li.setAttribute("aria-hidden", "false");
        }
        ul.querySelectorAll("li").forEach(x => x.classList.remove("is-ghost", "is-target", "is-dragging"));
        refreshPos(ul);
        dragLi = null;
      };

      document.addEventListener("pointermove", onMove, { passive: false });
      document.addEventListener("pointerup", cleanup);
      document.addEventListener("pointercancel", cleanup);
    };

    ul.addEventListener("pointerdown", down, { passive: false });
  };
  $$("ul.disc-list", wizardEl).forEach(makeSortable);

  // ---------- open / close wizard ----------
  const lockScroll = (lock) => {
    document.documentElement.style.overflow = lock ? "hidden" : "";
    document.body.style.overflow = lock ? "hidden" : "";
  };

  let lastFocus = null;
  const openWizard = () => {
    if (finished) { resultEl.scrollIntoView({ behavior: "smooth", block: "start" }); return; }
    lastFocus = document.activeElement;
    wizardEl.classList.add("is-open");
    wizardEl.setAttribute("aria-hidden", "false");
    lockScroll(true);
    btnClose.focus({ preventScroll: true });
    render();
    requestAnimationFrame(() => {
      const y = wizardEl.getBoundingClientRect().top + window.scrollY - 24;
      window.scrollTo({ top: y, behavior: "smooth" });
    });
  };
  const closeWizard = () => {
    wizardEl.classList.remove("is-open");
    wizardEl.setAttribute("aria-hidden", "true");
    lockScroll(false);
    if (lastFocus && lastFocus.focus) lastFocus.focus({ preventScroll: true });
  };

  btnOpen.addEventListener("click", openWizard);
  $("fabScroll") && $("#fabScroll").addEventListener("click", (e) => {
    e.preventDefault();
    resultEl.scrollIntoView({ behavior: "smooth", block: "start" });
  });
  btnClose.addEventListener("click", () => {
    hideResult();
    closeWizard();
    pageMain.scrollIntoView({ behavior: "smooth", block: "start" });
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && wizardEl.classList.contains("is-open")) closeWizard();
  });

  // ---------- scoring ----------
  const collect = () => {
    const out = [];
    $$("ul.disc-list", wizardEl).forEach(ul => {
      $$(":scope > li", ul).forEach((li, idx) => out.push({ pos: idx, type: li.dataset.type }));
    });
    return out;
  };
  const score = (payload) => {
    const maj = [], min = [];
    payload.forEach(x => { if (x.pos === 0) maj.push(x.type); if (x.pos === 3) min.push(x.type); });
    const cnt = (a, c) => a.reduce((n, x) => n + (x === c ? 1 : 0), 0);
    return {
      d: cnt(maj,"d") - cnt(min,"d"),
      i: cnt(maj,"i") - cnt(min,"i"),
      s: cnt(maj,"s") - cnt(min,"s"),
      c: cnt(maj,"c") - cnt(min,"c"),
    };
  };

  const LABELS = {
    d:"Доминирование", i:"Влияние", s:"Стабильность", c:"Соблюдение",
    D:"Доминирование", I:"Влияние", S:"Стабильность", C:"Соблюдение",
  };
  const DESC = {
    d:"Прагматичность, решительность, ориентация на результат и задачу. Не боится конфликтов, если они ведут к решению. Предпочитает действовать первым, не дожидаться.",
    i:"Коммуникабельность, оптимизм, ориентация на людей и эмоции. Убеждает, увлечённо и увлекает за собой, быстро меняет направление, если ситуация изменилась.",
    s:"Надёжность, спокойствие, ориентация на процесс и на людей рядом. Предпочитает компромисс и удержание, чем смену. Держит команду в устойчивом состоянии.",
    c:"Системность, внимание к деталям, ориентация на правила и процедуры. Принимает решения на основе анализа и фактов, сначала собирает данные, потом действует.",
  };

  const renderResult = (res) => {
    $("#scoreLine").textContent = `D:${res.d}, I:${res.i}, S:${res.s}, C:${res.c}`;
    const max = Math.max(1, ...[res.d, res.i, res.s, res.c].map(v => Math.abs(v)));
    const pct = v => v <= 0 ? 3 : Math.round((v / max) * 88 + 6);
    const setBar = (k, v) => {
      $("#val" + k).textContent = v;
      $("#bar" + k).style.width = pct(v) + "%";
    };
    setBar("D", res.d); setBar("I", res.i); setBar("S", res.s); setBar("C", res.c);

    // radar: D up, I right, S down, C left
    const cx = 105, cy = 118, R = 92;
    const ANGS = { d: -90, i: 0, s: 90, c: 180 };
    const V = { d:res.d, i:res.i, s:res.s, c:res.c };
    const pt = (k, r) => {
      const a = (ANGS[k] * Math.PI) / 180;
      return [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
    };
    const poly = (r, keys) => keys.map(k => pt(k, r).join(",")).join(" ");
    const spokes = Object.keys(ANGS).map(k => `M${cx} ${cy} L${pt(k,R).join(" ")}`).join(" ");
    const keys = ["d","i","s","c"];
    const vals = keys.map(k => pt(k, Math.abs(V[k]) / max * R * 0.92).join(",")).join(" ");
    const labels = [
      ["D", cx, cy - R - 14],
      ["I", cx + R + 18, cy + 5],
      ["S", cx, cy + R + 20],
      ["C", cx - R - 18, cy + 5],
    ];
    $("#radar").innerHTML =
      `<svg viewBox="0 0 210 236" role="img" aria-label="${ "D,I,S,C".split(",").map(k => `${k}:${ "dics".indexOf(k.toLowerCase()) >= 0 ? [] : [] }`).join("") }">
        <polygon points="${poly(R, keys)}" fill="none" stroke="rgba(0,0,0,.14)" stroke-width="1"/>
        <polygon points="${poly(R*.55, keys)}" fill="none" stroke="rgba(0,0,0,.09)" stroke-width="1"/>
        <polygon points="${poly(R*.28, keys)}" fill="none" stroke="rgba(0,0,0,.05)" stroke-width="1"/>
        <path d="${spokes}" stroke="rgba(0,0,0,.10)" fill="none"/>
        <polygon points="${vals}" fill="rgba(31,91,214,.20)" stroke="#1F5BD6" stroke-width="2" stroke-linejoin="round"/>
        ${keys.map(k => { const [x,y]=pt(k, Math.abs(V[k])/max * R * 0.92); return `<circle cx="${x}" cy="${y}" r="4.5" fill="#1F5BD6" stroke="#fff" stroke-width="1.6"/>`; }).join("")}
        ${labels.map(([l,x,y]) => `<text x="${x}" y="${y}" font-size="15" font-weight="800" text-anchor="middle" fill="#54637A">${l}</text>`).join("")}
      </svg>`;

    // notes: strongest positive trait, second strongest if available, weakest
    const entries = Object.entries(res);
    const topPositive = entries.filter(e => e[1] > 0).sort((a,b) => b[1]-a[1]);
    const topNegative = entries.filter(e => e[1] < 0).sort((a,b) => Math.abs(b[1]) - Math.abs(a[1]));
    const notes = $("#resultNotes");
    notes.innerHTML = "";
    const add = (cls, lab, html) => {
      const d = document.createElement("div");
      d.className = "res-note " + cls;
      d.innerHTML = `<span class="res-note__lab">${lab}</span><p>${html}</p>`;
      notes.appendChild(d);
    };
    if (topPositive.length) {
      const [k, v] = topPositive[0];
      add("res-note--top", "Сильная сторона",
          `<b>${LABELS[k]}</b> — ${DESC[k]}`);
      if (topPositive.length > 1) {
        const [k2] = topPositive[1];
        add("", "Вторая по силе",
            `<b>${LABELS[k2]}</b> — ${DESC[k2]}`);
      }
    }
    if (topNegative.length) {
      const [k] = topNegative[0];
      add("res-note--low", "Наименее",
          `<b>${LABELS[k]}</b> — эта черта в вашей структуре проявляется заметно реже. По контексту задачи вы скорее уступаете, чем инициируете.`);
    }

    // show
    resultEl.querySelectorAll(".res-col").forEach(c => c.classList.add("is-open"));
    wizardEl.style.display = "none";
    btnOpen.style.display = "none";
    fabDone.classList.add("is-open");
    fabDone.scrollIntoView({ behavior: "smooth", block: "nearest" });
    setTimeout(() => resultEl.scrollIntoView({ behavior: "smooth", block: "start" }), 80);
  };

  const hideResult = () => {
    resultEl.querySelectorAll(".res-col").forEach(c => c.classList.remove("is-open"));
    $("#resultNotes").innerHTML = "";
    ["D","I","S","C"].forEach(k => {
      $("#bar" + k).style.width = "0%";
      $("#val" + k).textContent = "0";
    });
  };

  const reset = () => {
    finished = false;
    hideResult();
    wizardEl.style.display = "";
    btnOpen.style.display = "";
    fabDone.classList.remove("is-open");

    // restore original order of items in each ul
    const uls = $$("ul.disc-list", wizardEl);
    uls.forEach((ul, idx) => {
      const order = O[idx];
      const map = new Map($$(":scope > li", ul).map(li => [li.dataset.text, li]));
      order.forEach(([t, txt]) => {
        const li = map.get(txt);
        if (li) ul.appendChild(li);
      });
      refreshPos(ul);
    });

    step = 0;
    render();
    pageMain.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  btnFinish.addEventListener("click", () => {
    const res = score(collect());
    finished = true;
    renderResult(res);
  });
  $("#btnRestart").addEventListener("click", reset);
  $("#btnPageTop").addEventListener("click", () => pageMain.scrollIntoView({ behavior: "smooth", block: "start" }));

  render();
})();

