const { JSDOM } = require('jsdom');
const fs = require('fs');
const dom = new JSDOM(fs.readFileSync('index.html','utf8'), { runScripts: 'dangerously', pretendToBeVisual: true });
const { window } = dom;
const { document } = window;
window.matchMedia = window.matchMedia || (q => ({ matches:false, media:q, addListener(){}, removeListener(){}, addEventListener(){}, removeEventListener(){} }));
// polyfill scrollTo etc.
window.HTMLElement.prototype.scrollTo = function(opts){};
window.Element.prototype.scrollTo = function(opts){};
window.HTMLElement.prototype.focus = function(opts){};
window.scrollTo = () => {};

// Simulate a full test pass: for each card, move items to a known deterministic order
// so the final score is deterministic and we can verify.
const uls = Array.from(document.querySelectorAll('ul.disc-list'));
console.log('cards:', uls.length, 'items per:', uls.map(u=>u.children.length).join(','));

// For scoring test: put every D first and last for each card
// Strategy: for each ul, sort li by type: put 'c' at bottom (pos 3), 'd' at top (pos 0)
// Then compute expected: +1 d (24), -1 c (24) → D=24, C=-24, I=0, S=0
uls.forEach(ul => {
  const lis = Array.from(ul.children);
  lis.sort((a,b) => {
    // d first, then i, s, c
    const rank = { d:0, i:1, s:2, c:3 };
    return rank[a.dataset.type] - rank[b.dataset.type];
  });
  lis.forEach(li => ul.appendChild(li));
});

